patch:
diff --git a/repro/no-var-tdz.mjs b/repro/no-var-tdz.mjs
new file mode 100644
index 0000000..1e47107
--- /dev/null
+++ b/repro/no-var-tdz.mjs
@@ -0,0 +1,28 @@
+// Reproduction for eslint/eslint#20209: no-var autofix produces code that throws ReferenceError.
+import { Linter } from "../lib/api.js";
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+
+const linter = new Linter();
+const config = { rules: { "no-var": "error" } };
+const { output, messages, fixed } = linter.verifyAndFix(code, config, { filename: "repro.mjs" });
+
+console.log("--- messages (before fix) ---");
+console.log(linter.verify(code, config, { filename: "repro.mjs" }).map(m => `${m.line}:${m.column} ${m.message} fix=${!!m.fix}`).join("\n"));
+console.log("--- fixed:", fixed, "---");
+console.log(output);
+
+const run = src => {
+    const body = src.replace("export ", "");
+    const fn = new Function(`${body}; return a();`);
+    const log = console.log; console.log = () => {};
+    try { fn(); return "ok"; } catch (e) { return `${e.name}: ${e.message}`; } finally { console.log = log; }
+};
+console.log("--- runtime ---");
+console.log("original:", run(code));
+console.log("fixed:   ", run(output));
+if (fixed && run(output) !== "ok") { console.log("BUG REPRODUCED: no-var fix introduced a TDZ ReferenceError"); process.exitCode = 1; }
